B.aNw=s(["\uc751, \ucc9c\ucc9c\ud788 \ub9d0\ud574 \uc918.","\ub124 \uc598\uae30\ub294 \uc801\uc5b4 \ub458\uac8c.","\uc624\ub298 \ub9c8\uc74c\uae4c\uc9c0 \uac19\uc774 \uae30\ub85d\ud574 \ub458\uae4c?","\ubb34\uc2a8 \ub9d0\uc778\uc9c0 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4 \ubcfc\uac8c.","\ub124\uac00 \uba3c\uc800 \ub9d0\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\uc6b0\ub9ac\uac00 \uc313\uc740 \uae30\ub85d\uc774 \uc788\uc73c\ub2c8\uae4c \uad1c\ucc2e\uc544."],t.s)
B.aNm=s(["\uc544\uc9c1 \uc624\ub298 \uacb0\uacfc\ud45c\uac00 \uc5c6\uc5b4\uc11c \ub2e8\uc815\ud558\uba74 \uc548 \ub420 \uac83 \uac19\uc544.","\uc7a5\uc740 \uc26c\uc5b4\ub3c4 \uc9c0\ub09c \uae30\ub85d\uc740 \uc815\ub9ac\ud560 \uc218 \uc788\uc5b4.","\uc624\ub298\uc740 \ud070 \ubcc0\ud654 \uc5c6\uc774 \ubc84\ud2f4 \ub0a0\uc774\ub124.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \ub204\uc801\ub3c4 \ud50c\ub7ec\uc2a4\ub77c \ub2e4\ud589\uc774\uc57c.","\uc624\ub298\uc740 \ubc8c\uc5c8\uc9c0\ub9cc \uc804\uccb4\ub85c\ub294 \uc544\uc9c1 \uc190\uc2e4\uc774\uc57c. \uadf8\ub798\ub3c4 \ud68c\ubcf5 \uc911\uc774\ub124.","\uc624\ub298 \uc190\uc2e4\uc740 \ub0ac\uc9c0\ub9cc \ub204\uc801 \uc218\uc775\uc740 \ub0a8\uc544 \uc788\uc5b4.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \ub204\uc801\ub3c4 \ub9c8\uc774\ub108\uc2a4\ub77c \ub9c8\uc74c\uc774 \ubb34\uac81\uaca0\ub2e4."],t.s)
